import itertools

def is_colorful(m, n):
    # n is number of flavors, m is circle size
    # Condition: any group of n+1 consecutive candies contains all n flavors
    for p in itertools.product(range(n), repeat=m):
        possible = True
        for i in range(m):
            block = set()
            for j in range(n + 1):
                block.add(p[(i + j) % m])
            if len(block) < n:
                possible = False
                break
        if possible:
            return True
    return False

