def check_colorful(m, n):
    # Try to find a sequence of length m using n flavors
    # such that every window of n+1 has all n flavors.
    # Using backtracking to find the sequence.

    seq = [-1] * m

    def is_valid(pos, flavor):
        # Check all windows of size n+1 that include pos
        # A window starting at i and ending at i+n
        # includes pos if i <= pos <= i+n
        # Since it's a circle, we need to handle wrapping.

        # To make it easier, let's just check the condition at the end, 
        # or check it partially.
        # If we are at pos, we can check the window starting at pos - n.
        # The window starting at pos-n ends at pos.
        # It's fully filled if pos >= n.

        # But we are filling from 0 to m-1.
        # At pos, we can't fully check the window [pos-n, pos] until we've filled up to pos.
        # And we can't fully check windows that wrap around until the end.
        return True

    def solve(pos):
        if pos == m:
            # Final check for all windows, including wrapping
            for i in range(m):
                block = set()
                for j in range(n + 1):
                    block.add(seq[(i + j) % m])
                if len(block) < n:
                    return False
            return True

        for flavor in range(n):
            seq[pos] = flavor
            # Partial check: windows that are now fully filled and don't wrap
            if pos >= n:
                # Window starting at pos - n, ending at pos
                block = set()
                for j in range(pos - n, pos + 1):
                    block.add(seq[j])
                if len(block) < n:
                    continue

            if solve(pos + 1):
                return True
        return False

    return solve(0)

