def is_colorful_backtrack(m, n):
    seq = [-1] * m

    def solve(pos):
        if pos == m:
            # Check wrap-around windows
            for i in range(m - n, m):
                block = set()
                for j in range(n + 1):
                    block.add(seq[(i + j) % m])
                if len(block) < n:
                    return False
            return True

        # Try flavors that are more likely to work
        # For example, a flavor that is not already in the current window
        # This is a heuristic, not a guarantee.

        # Let's just try all flavors.
        for flavor in range(n):
            seq[pos] = flavor
            if pos >= n:
                block = set()
                for j in range(pos - n, pos + 1):
                    block.add(seq[j])
                if len(block) < n:
                    continue
            if solve(pos + 1):
                return True
        return False

    return solve(0)

